// Cherche le texte dans tous les champs possibles
const text = 
  $json.output || 
  $json.Output || 
  $json.agent_output || 
  $json.message || 
  $json.text || 
  $json.response ||
  "";

// Debug : afficher ce qu'on a trouvé
console.log("Clés disponibles:", Object.keys($json));
console.log("Texte trouvé:", text.substring(0, 100));

// Si vide → erreur
if (!text || text.trim().length === 0) {
  return [{ json: { 
    error: "Aucun texte à envoyer",
    available_keys: Object.keys($json)
  } }];
}

// Découpe en chunks
const chunkSize = 4000;
const messages = [];

for (let i = 0; i < text.length; i += chunkSize) {
  messages.push({ 
    json: { 
      message: text.slice(i, i + chunkSize),
      chunk_index: Math.floor(i / chunkSize) + 1,
      total_chunks: Math.ceil(text.length / chunkSize)
    } 
  });
}

console.log(`Divisé en ${messages.length} chunks`);
return messages;

